import {
  APP_COMPANY_CRM_NAME,
  APP_COMPANY_NAME,
} from "@/constants/appBranding";
import { APP_EMAIL_LOGO_SRC } from "@/constants/appLogo";

export { APP_COMPANY_CRM_NAME, APP_COMPANY_NAME };

export const APPLICATION_APPROVAL_EMAIL_SUBJECT =
  "Your Application Has Been Approved";

export const OFFER_UPDATED_EMAIL_SUBJECT =
  "Your Offer Values Have Been Updated";

/**
 * Server-only values are generated by the backend (public approval portal URL with
 * a signed token, the resolved ISO recipient name, and the deal business name). The
 * frontend renders these placeholders into the email HTML and the backend swaps them
 * for the real values before sending — mirrors the document-request upload-url flow.
 */
export const APPLICATION_APPROVAL_URL_PLACEHOLDER =
  "__APPLICATION_APPROVAL_URL__";
export const APPLICATION_APPROVAL_CLIENT_NAME_PLACEHOLDER =
  "__APPROVAL_CLIENT_NAME__";
export const APPLICATION_APPROVAL_COMPANY_NAME_PLACEHOLDER =
  "__APPROVAL_COMPANY_NAME__";

/** Hosted logo for outbound email (Gmail/Outlook-safe absolute URL). */
export const APPLICATION_APPROVAL_EMAIL_LOGO_SRC = APP_EMAIL_LOGO_SRC;

/** Center faded background watermark layout image. */
export const APPLICATION_APPROVAL_EMAIL_WATERMARK_SRC =
  APPLICATION_APPROVAL_EMAIL_LOGO_SRC;

export const CLIENT_PROVIDED_STIPS = [
  "Voided check",
  "Drivers license",
] as const;

export const COMPANY_HANDLED_STIPS = [
  "Bank Login (DecisionLogic or Manual)",
  "Cc Processing Statement or AR Report/Invoices",
  "Merchant interview / Funding Call",
] as const;

export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/** Encode a URL for use in an HTML href attribute (preserves the merge-field placeholder). */
export function escapeHrefAttribute(url: string): string {
  if (url === APPLICATION_APPROVAL_URL_PLACEHOLDER) {
    return url;
  }
  return escapeHtml(url);
}

export type ApplicationApprovalEmailFields = {
  clientName: string;
  companyName: string;
  /** Public ISO approval portal — single link for approval + offer-updated CTAs. */
  isoApprovalUrl: string;
  viewApplicationUrl: string;
  calculateApprovalUrl: string;
  viewCommentUrl: string;
  companyNameBrand: string;
  crmName: string;
};

/** One canonical public approval link for both email templates. */
export function resolveIsoApprovalUrl(
  values: Record<string, string | undefined>,
): string {
  return (
    String(
      values.calculate_approval_url || values.view_application_url || "",
    ).trim() || APPLICATION_APPROVAL_URL_PLACEHOLDER
  );
}

export function resolveApplicationApprovalEmailFields(
  values: Record<string, string | undefined>,
): ApplicationApprovalEmailFields {
  const clientName =
    String(values.client_name || "").trim() || "Valued Client";
  const companyName =
    String(values.company_name || "").trim() || "your company";
  const isoApprovalUrl = resolveIsoApprovalUrl(values);

  return {
    clientName,
    companyName,
    isoApprovalUrl,
    viewApplicationUrl: isoApprovalUrl,
    calculateApprovalUrl: isoApprovalUrl,
    viewCommentUrl: isoApprovalUrl,
    companyNameBrand: APP_COMPANY_NAME,
    crmName: APP_COMPANY_CRM_NAME,
  };
}
